export async function openStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('private-pilot-prep',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
export async function readState(db){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function writeState(db,state){const snapshot=structuredClone(state);return new Promise((resolve,reject)=>{const t=db.transaction('state','readwrite');t.objectStore('state').put(snapshot,'main');t.oncomplete=()=>resolve();t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('Save interrupted'));});}
